add_filter( 'wc_order_is_editable', 'perfectpixel_editable_order_statuses', 10, 2 );

function perfectpixel_editable_order_statuses( $editable, $order ) {
	$statuses = array_filter( array_map( 'sanitize_key', explode( ',', '{{editable_order_statuses}}' ) ) );
	return ( $statuses && $order->has_status( $statuses ) ) ? true : $editable;
}
